private Scene createAndConfigScene(MainView mainView,Injector injector){
  try {
    Rectangle maxWindowBounds=GraphicsEnvironment.getLocalGraphicsEnvironment().getMaximumWindowBounds();
    Scene scene=new Scene(mainView.getRoot(),maxWindowBounds.width < INITIAL_WINDOW_WIDTH ? (maxWindowBounds.width < MIN_WINDOW_WIDTH ? MIN_WINDOW_WIDTH : maxWindowBounds.width) : INITIAL_WINDOW_WIDTH,maxWindowBounds.height < INITIAL_WINDOW_HEIGHT ? (maxWindowBounds.height < MIN_WINDOW_HEIGHT ? MIN_WINDOW_HEIGHT : maxWindowBounds.height) : INITIAL_WINDOW_HEIGHT);
    scene.getStylesheets().setAll("/bisq/desktop/bisq.css","/bisq/desktop/images.css","/bisq/desktop/CandleStickChart.css");
    addSceneKeyEventHandler(scene,injector);
    return scene;
  } catch (HeadlessException e) {
    throw new RuntimeException("Cannot create scene in headless environment", e);
  }
}
